import { describe, test, expect } from 'vitest';
import { Button } from './zimmButton.css';

/**
 * index.test.tsx renders through the real ChakraProvider/theme (not mocked), so the base
 * (non-media-query) recipe values ARE exercised there. But JSDOM does not evaluate real
 * @media breakpoints, so a rendered-component test can't verify what changes — or doesn't —
 * inside a size's @media block. These assertions read the plain recipe object directly.
 */
describe('ZimmButton recipe — social size padding regression guard', () => {
  test('px is 32px (action-padding-h-lg) at the base/mobile level, not the 20px md-tier token', () => {
    // Corrected 2026-09: this previously read var(--zimm-size-action-padding-h-md) (20px),
    // matching a comment that wrongly claimed Figma had padding step down on mobile — live
    // Figma inspection confirmed padding is 32px at every breakpoint.
    // Button.sizes is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts
    // always passes a sizes object — guaranteed non-null at runtime.
    const social = Button.sizes!.social as Record<string, unknown>;
    expect(social.px).toBe('var(--zimm-size-action-padding-h-lg)');
  });

  test('the md-breakpoint override no longer touches px — height/typography still step, padding does not', () => {
    // Button.sizes is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts
    // always passes a sizes object — guaranteed non-null at runtime.
    const social = Button.sizes!.social as Record<string, unknown>;
    const mediaKey = Object.keys(social).find((key) => key.startsWith('@media'));
    expect(mediaKey).toBeDefined();

    const mediaOverride = social[mediaKey as string] as Record<string, unknown>;
    expect(mediaOverride).not.toHaveProperty('px');
    // Confirms these are still deliberately responsive — only px was the bug.
    expect(mediaOverride).toHaveProperty('h');
    expect(mediaOverride).toHaveProperty('fontSize');
    expect(mediaOverride).toHaveProperty('lineHeight');
    expect(mediaOverride).toHaveProperty('textStyle');
  });
});

