168	/** Properties that resolve through `theme.space`, where a bare scale key is correct. */
169	const SPACE_SHORTHANDS = new Set(['padding', 'margin', 'inset', 'gap', 'p', 'm']);
170	
171	/** Derived from the registered breakpoints so the two cannot drift apart. */
172	const BREAKPOINT_KEYS = new Set(Object.keys(breakpoints));
173	
174	/**
175	 * True when `n` is a responsive *value* container — an array (`['xl','2xl']`) or a
176	 * breakpoint-keyed object (`{base:'xl', md:'2xl'}`) — rather than a style object. Its keys are
177	 * therefore positions, not property names, and the property name has to come from the parent.
178	 *
179	 * The test is deliberately "are ALL the keys breakpoints?" and not "is ANY key a breakpoint?".
180	 * That is load-bearing: `xl` and `2xl` are keys in `breakpoints` AND in `spacing`, and
181	 * `sm`/`md`/`lg` are keys in `breakpoints` AND in `fontSizes`/`lineHeights`/`letterSpacings`.
182	 * A per-key test cannot tell a responsive map apart from a style object, so only the all-keys
183	 * form works.
184	 *
185	 * A Chakra `sizes`/`variants` map whose every member happens to be named after a breakpoint
186	 * (`sizes: {md: {...}, lg: {...}}`) does read as responsive here, but harmlessly: the level
187	 * below it is a real style object, which re-establishes the property name before any leaf is
188	 * reported.
189	 */
190	const isResponsiveContainer = (n: object): boolean =>
191	  Array.isArray(n) || (Object.keys(n).length > 0 && Object.keys(n).every((k) => BREAKPOINT_KEYS.has(k)));
192	
193	type Found = { recipe: string; path: string; prop: string; value: string };
194	
195	/**
196	 * Recursively walk a style object, including nested media queries, pseudo-selectors and
197	 * responsive containers. `prop` carries the nearest enclosing property name forward so a leaf
198	 * inside a responsive container is attributed to the property, not to `0` or `base`.
199	 */
200	const walk = (node: unknown, recipe: string, path: string, prop: string, hit: (f: Found) => void): void => {
201	  if (node === null || typeof node !== 'object') return;
202	  const responsive = isResponsiveContainer(node);
203	  for (const [key, value] of Object.entries(node as Record<string, unknown>)) {
204	    const here = path ? `${path}.${key}` : key;
205	    const p = responsive ? prop : key;
206	    if (value !== null && typeof value === 'object') {
207	      walk(value, recipe, here, p, hit);
208	    } else if (typeof value === 'string') {
209	      hit({ recipe, path, prop: p, value });
210	    }
211	  }
212	};
213	
214	/**
215	 * `recipe.path.prop: 'value'`. For a responsive hit `path` already ends in the property name
216	 * (the array/breakpoint object sits *under* `fontSize`), so appending `prop` again would read
217	 * `…fontSize.fontSize`.
218	 */
219	const where = (f: Found): string => {
220	  const segments = f.path ? f.path.split('.') : ['baseStyle'];
221	  if (segments[segments.length - 1] !== f.prop) segments.push(f.prop);
222	  return `${f.recipe}.${segments.join('.')}: '${f.value}'`;
223	};
224	
225	/** Default resolution props for a function-form baseStyle — all boolean flags false. */
226	const DEFAULT_STYLE_PROPS: Record<string, unknown> = {
227	  inverse: false,
228	  disabled: false,
229	  hasError: false,
230	  focused: false,
231	  filled: false,
232	  theme,
233	  colorMode: 'light',
234	};
235	
236	/**
237	 * Every combination of DEFAULT_STYLE_PROPS's boolean-valued entries (theme/colorMode held
238	 * fixed) — 2^5 = 32 today. A function-form baseStyle can branch its VALUE, not just its
239	 * shape, on any of these (`top: floated ? '3xs' : '50%'` in zimmTextInput.css.ts), so
240	 * resolving with only the all-false default can leave a branch's value completely unwalked —
241	 * '3xs' shipped exactly this way: `floated` is false under the all-default combo, so the
242	 * guard below never saw the string it was meant to catch. Exhaustive, not sampled: n is
243	 * small enough that 2^n costs nothing, and a missed combination is the whole failure mode.
244	 */
245	const booleanKeys = Object.keys(DEFAULT_STYLE_PROPS).filter((k) => typeof DEFAULT_STYLE_PROPS[k] === 'boolean');
246	const PROP_COMBINATIONS: Record<string, unknown>[] = Array.from({ length: 2 ** booleanKeys.length }, (_, i) => {
247	  const combo = { ...DEFAULT_STYLE_PROPS };
248	  booleanKeys.forEach((key, bit) => {
249	    combo[key] = Boolean(i & (1 << bit));
250	  });
251	  return combo;
252	});
253	
254	/** baseStyle may be a plain object or a function of props (see zimmTextInput). Resolves with
255	 *  the all-false default only — for checks that need just the structural shape (which part
256	 *  keys exist), not every value a branch could produce. */
257	const resolveBaseStyle = (recipe: Record<string, unknown>): unknown => {
258	  const bs = recipe.baseStyle;
259	  if (typeof bs !== 'function') return bs;
260	  return (bs as (p: Record<string, unknown>) => unknown)(DEFAULT_STYLE_PROPS);
261	};
262	
263	/** Every value a function-form baseStyle can produce, across every prop combination. A
264	 *  plain-object baseStyle has only the one "combination" (itself). The value-level guards
265	 *  below walk this, not resolveBaseStyle's single default resolution — see PROP_COMBINATIONS. */
266	const resolveAllBaseStyles = (recipe: Record<string, unknown>): unknown[] => {
267	  const bs = recipe.baseStyle;
268	  if (typeof bs !== 'function') return [bs];
269	  return PROP_COMBINATIONS.map((props) => (bs as (p: Record<string, unknown>) => unknown)(props));
270	};
271	
272	const collect = (): Found[] => {
273	  const found: Found[] = [];
274	  for (const [name, recipe] of Object.entries(components)) {
275	    const r = recipe as unknown as Record<string, unknown>;
276	    for (const resolved of resolveAllBaseStyles(r)) {
277	      walk(resolved, name, '', '', (f) => found.push(f));
278	    }
279	    for (const section of [r.variants, r.sizes]) {
280	      walk(section, name, '', '', (f) => found.push(f));
281	    }
282	  }
283	  // resolveAllBaseStyles calls a function-form baseStyle once per prop combination (32
284	  // today), and most lines don't depend on the varying prop at all — the same Found would
285	  // otherwise appear dozens of times in a failing test's offender list.
286	  const seen = new Set<string>();
287	  return found.filter((f) => {
288	    const key = where(f);
289	    if (seen.has(key)) return false;
290	    seen.add(key);
291	    return true;
292	  });
293	};
294	
295	describe('recipe guards', () => {
296	  test('collect() actually walks the registered recipes', () => {
297	    // Every other test here asserts an empty offender list, which an empty input satisfies
298	    // just as well as a clean one. Without this, deleting `components` would turn the whole
299	    // file green.
300	    expect(Object.keys(components).length).toBeGreaterThan(0);
301	    expect(collect().length).toBeGreaterThan(0);
302	  });
303	
304	  test('no sizing property uses a bare spacing-scale key', () => {
305	    const offenders = collect()
306	      .filter((f) => SIZING_PROPS.has(f.prop) && SPACING_KEYS.includes(f.value))
307	      .map(where);
308	
309	    // `width: 'xl'` reads theme.sizes.xl (36rem), not space.xl (1.5rem).
310	    // Use var(--zimm-scale-*), an imported constant, or an explicit unit instead.
311	    expect(offenders).toEqual([]);
312	  });
313	
314	  test('no typography property uses a bare scale key', () => {
315	    const offenders = collect()
316	      .filter((f) => TYPOGRAPHY_PROPS.get(f.prop)?.has(f.value) ?? false)
317	      .map(where);
318	
319	    // `fontSize: '2xs'` reads Chakra's fontSizes (10px), not the Zimmermann scale (14px);
320	    // `lineHeight: '2xs'` resolves to nothing at all. Use textStyle or var(--zimm-font-*).
321	    expect(offenders).toEqual([]);
322	  });
323	
324	  test('no compound shorthand contains a bare scale key', () => {
325	    const offenders = collect()
326	      .filter((f) => {
327	        if (!SPACE_SHORTHANDS.has(f.prop)) return false;
328	        if (!f.value.includes(' ')) return false; // single token is fine
329	        // Split on whitespace outside var(...) and look for a bare scale key.
330	        const parts = f.value.replace(/var\([^)]*\)/g, 'VAR').split(/\s+/);
331	        return parts.some((part) => SPACING_KEYS.includes(part));
332	      })
333	      .map(where);
334	
335	    // Chakra resolves a token only as a whole value. `padding: 'xs 0'` is emitted verbatim
336	    // and the browser drops the declaration. Use paddingY/paddingX or a var() instead.
337	    expect(offenders).toEqual([]);
338	  });
339	
340	  test('no override-component style uses a bare token key on a registered scale', () => {
341	    const offenders = collect()
342	      .filter(
343	        (f) =>
344	          (SPACE_PROPS.has(f.prop) && SPACING_KEYS.includes(f.value)) ||
345	          (COLOR_PROPS.has(f.prop) && COLOR_KEYS.has(f.value)),
346	      )
347	      .map(where);
348	
349	    // Not a wrong-value bug — space and colors ARE registered Chakra scales, so `gap: 'xs'` and
350	    // `color: 'text.inverse'` already resolve to the correct Zimmermann value. House style
351	    // instead: use var(--zimm-scale-*) / var(--zimm-color-*) so every call site is an
352	    // unambiguous zimm reference, not something a reviewer has to check against theme/index.ts's
353	    // registered-scale list to know whether it's correct.
354	    expect(offenders).toEqual([]);
355	  });
356	
357	  test('no recipe silently inherits a base SFCC recipe of the same name', () => {
358	    // extendTheme DEEP MERGES. These three intentionally share a base key: Button wants the
359	    // base variants, and Header/ListMenu are partial overrides of components whose other
360	    // parts we still rely on. Anything else must be namespaced (e.g. ZimmFooter, not Footer).
361	    const INTENTIONAL_MERGES = ['Button', 'Header', 'ListMenu'];
362	
363	    const unexpected = Object.keys(components)
364	      .filter((name) => !INTENTIONAL_MERGES.includes(name))
365	      .filter((name) => {
366	        const ours = resolveBaseStyle(components[name as keyof typeof components] as never) ?? {};
367	        const merged = resolveBaseStyle((theme.components?.[name] ?? {}) as Record<string, unknown>) ?? {};
368	        const ourKeys = new Set(Object.keys(ours as object));
369	        // A key present after composition that we never declared came from the base theme.
370	        return Object.keys(merged as object).some((k) => !ourKeys.has(k));
371	      });
372	
373	    expect(unexpected).toEqual([]);
374	  });
375	});
